<template>
  <Header />
  <main class="mx-auto w-full min-w-0 max-w-6xl space-y-6 px-4 pb-16 pt-28 sm:px-8 sm:pt-36">
    <button type="button" class="text-sm font-bold text-slate-500 hover:text-blue-600" @click="goBack">← Назад</button>
    <p v-if="query.isPending.value" role="status" class="rounded-3xl bg-white p-10 text-center text-slate-500">Загружаем профиль…</p>
    <p v-if="query.error.value" role="alert" class="rounded-2xl bg-rose-50 p-5 text-sm text-rose-700">{{ query.error.value.message }} <button class="font-bold underline" @click="query.refetch()">Повторить</button></p>
    <template v-if="data">
      <section class="relative overflow-hidden rounded-3xl bg-gradient-to-br from-slate-950 via-blue-950 to-slate-900 p-6 text-white sm:p-9">
        <div class="flex flex-wrap items-center gap-5 sm:gap-7"><StaffPhoto :role="role" :id="id" class="!h-28 !w-28 !rounded-2xl !bg-white/10 sm:!h-36 sm:!w-36" /><div class="min-w-0 flex-1"><p class="text-xs font-bold uppercase tracking-[.2em] text-blue-300">{{ role==='coach'?'Тренер НБА':'Руководитель клуба НБА' }}</p><h1 class="mt-3 text-3xl font-black sm:text-5xl">{{ data.name }}</h1><p class="mt-4 flex flex-wrap gap-x-4 gap-y-2 text-sm text-blue-100"><span v-if="age">{{ data.deathDate?'На момент смерти: ':'' }}{{ age }}</span><span v-if="data.birthDate">Родился {{ date(data.birthDate) }}</span><span v-if="data.deathDate">Умер {{ date(data.deathDate) }}</span></p></div></div>
      </section>
      <section class="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6">
        <div class="flex flex-wrap items-end justify-between gap-4"><div><h2 class="text-xl font-black text-slate-900">Результаты сезона</h2><p class="mt-2 text-xs leading-5 text-slate-500">Место команды в регулярном чемпионате и достигнутая стадия плей-офф.</p></div><label class="text-xs font-bold text-slate-500">Сезон<select v-model="season" aria-label="Сезон тренера или руководителя" class="mt-2 block rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-800"><option v-for="s in seasons" :key="s" :value="s">{{ s }}</option></select></label></div>
        <p v-if="results.isFetching.value" role="status" class="mt-5 text-sm text-slate-500">Загружаем результаты…</p>
        <p v-if="results.error.value" role="alert" class="mt-5 text-sm text-rose-700">{{ results.error.value.message }} <button class="font-bold underline" @click="results.refetch()">Повторить</button></p>
        <div v-if="results.data.value" class="mt-5 space-y-4"><article v-for="(item,index) in results.data.value.results" :key="`${item.stint.team.abbr}:${item.stint.position}:${index}`" class="rounded-2xl border border-slate-200 p-4 sm:p-5">
          <div class="flex items-center gap-3"><img v-if="item.stint.team.localLogo" :src="`/logos/${item.stint.team.abbr}.svg`" alt="" class="h-10 w-10 object-contain" /><div><RouterLink v-if="item.stint.team.localLogo && season>='2000-01'" :to="{path:`/team/${item.stint.team.abbr}`,query:{season}}" class="font-black text-slate-900 hover:text-blue-600">{{ item.stint.team.name }}</RouterLink><span v-else class="font-black text-slate-900">{{ item.stint.team.name }}</span><p class="mt-1 text-xs text-slate-500">{{ staffPosition(item.stint.position) }}<span v-if="item.stint.wins!=null"> · {{ item.stint.wins }}–{{ item.stint.losses }}</span></p></div></div>
          <div v-if="item.result" class="mt-5 grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-slate-50 p-4"><p class="text-[10px] font-bold uppercase tracking-wider text-slate-400">Регулярный чемпионат</p><strong class="mt-2 block text-lg text-slate-900">{{ item.result.conferenceRank ? `${item.result.conferenceRank}-е место ${item.result.rankScope==='division'?'в дивизионе':'в конференции'}` : 'Место не указано' }}</strong><p class="mt-1 text-xs text-slate-500">{{ item.result.conference==='east'?'Восток':item.result.conference==='west'?'Запад':'' }}<span v-if="item.result.wins!=null"> · итог команды {{ item.result.wins }}–{{ item.result.losses }}</span></p></div><div class="rounded-xl bg-blue-50 p-4"><p class="text-[10px] font-bold uppercase tracking-wider text-blue-500">Плей-офф</p><strong class="mt-2 block text-lg text-blue-950">{{ item.result.playoffResult }}</strong><p v-if="item.result.playoffPlace" class="mt-1 text-xs text-blue-700">{{ item.result.playoffPlace }}-е место</p><p v-if="item.stint.playoffGames" class="mt-1 text-xs text-blue-700">Баланс плей-ин / плей-офф: {{ item.stint.playoffWins }}–{{ item.stint.playoffLosses }} {{ role==='coach' && item.stint.position==='head'?'под руководством тренера':'' }}</p></div></div>
          <p v-else class="mt-4 text-sm text-slate-500">Итоговые места команды временно недоступны. <button class="font-bold text-blue-600" @click="results.refetch()">Повторить</button></p>
          <p v-if="item.result && role==='coach' && (item.stint.position==='assistant' || item.stint.games!==((item.result.wins || 0)+(item.result.losses || 0)))" class="mt-3 text-xs leading-5 text-slate-400">Показан итог команды за весь сезон. {{ item.stint.position==='assistant'?'В этом сезоне тренер работал ассистентом.':'В сезоне командой руководили несколько тренеров.' }}</p>
        </article><p v-if="!results.data.value.results.length" class="text-sm text-slate-500">В архиве нет данных за этот сезон.</p></div>
      </section>
      <section class="space-y-4 rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><h2 class="text-xl font-black text-slate-900">Команды в карьере</h2><div class="grid gap-3 sm:grid-cols-2"><article v-for="(item,index) in data.history" :key="index" class="flex items-center gap-3 rounded-2xl border border-slate-100 p-4"><img v-if="item.team.localLogo" :src="`/logos/${item.team.abbr}.svg`" alt="" class="h-10 w-10 shrink-0 object-contain" /><div class="min-w-0"><p class="font-bold text-slate-800">{{ item.team.name }}</p><p class="mt-1 text-xs text-slate-500">{{ item.startYear }}–{{ item.endYear+1 }} · {{ staffPosition(item.position) }}</p></div></article></div></section>
      <section class="space-y-4 rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><h2 class="text-xl font-black text-slate-900">Награды и титулы</h2><div v-if="data.awards.length" class="overflow-x-auto"><table class="w-full min-w-[350px] text-left text-sm"><thead class="border-b border-slate-200 text-xs text-slate-400"><tr><th class="py-3 pr-4">Сезон</th><th class="py-3">Награда</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="(award,index) in data.awards" :key="index"><td class="py-4 pr-4"><RouterLink v-if="award.season>='2000-01'" :to="{name:'SeasonAwards',query:{season:award.season,award:award.label==='Чемпион НБА'?'champions':award.label.includes('месяца')?'coach-month':'season'}}" class="font-bold text-blue-600 hover:underline">{{ award.season }}</RouterLink><span v-else>{{ award.season }}</span></td><td class="py-4 font-semibold text-slate-700">{{ award.label }}</td></tr></tbody></table></div><p v-else class="text-sm text-slate-500">В архиве пока нет записей о наградах.</p></section>
      <section class="overflow-hidden rounded-3xl border border-slate-200 bg-white"><h2 class="p-5 text-xl font-black text-slate-900 sm:p-6">История по сезонам</h2><div class="overflow-x-auto"><table class="w-full min-w-[680px] text-left text-xs"><thead class="border-y border-slate-100 bg-slate-50 text-[10px] uppercase text-slate-400"><tr><th class="px-5 py-3">Сезон</th><th class="px-3 py-3">Команда</th><th class="px-3 py-3">Роль</th><th class="px-3 py-3">Победы / поражения</th><th class="px-3 py-3" title="Место команды внутри дивизиона, если применимо">Место в дивизионе</th><th class="px-5 py-3">Матчи плей-ин / плей-офф</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="(item,index) in data.stints" :key="index" :class="season===item.season?'bg-blue-50/60':''"><td class="px-5 py-4"><button class="font-bold text-blue-600 hover:underline" @click="season=item.season">{{ item.season }}</button></td><td class="px-3 py-4 font-bold text-slate-800">{{ item.team.abbr }}</td><td class="px-3 py-4 text-slate-500">{{ staffPosition(item.position) }}</td><td class="px-3 py-4 text-slate-700">{{ item.wins!=null?`${item.wins}–${item.losses}`:'—' }}</td><td class="px-3 py-4 text-slate-500">{{ item.divisionRank || '—' }}</td><td class="px-5 py-4 text-slate-500">{{ item.playoffGames ?? '—' }}</td></tr></tbody></table></div></section>
      <p class="text-xs leading-6 text-slate-400">Результаты плей-офф указаны по достигнутой стадии. Числовое место показано для чемпиона и финалиста. <a :href="data.source" target="_blank" rel="noopener noreferrer" class="underline">Источник: Basketball Reference ↗</a></p>
    </template>
  </main>
</template>
<script setup lang="ts">
import {computed} from 'vue'
import Header from '../components/Headers/Header.vue'
import StaffPhoto from '../components/NBA/Staff/StaffPhoto.vue'
import {useStaffProfile} from '../composables/NBA/Staff/useStaffProfile'
import {staffPosition} from '../types/staff'
import {playerAgeLabel} from '../utils/playerAge'
import {usePageTitle} from '../composables/usePageTitle'
import {useBackNavigation} from '../composables/useBackNavigation'
const {role,id,query,season,seasons,results}=useStaffProfile(),data=query.data
const {goBack}=useBackNavigation('/season-awards')
const age=computed(()=>data.value?.birthDate?playerAgeLabel({birthDate:data.value.birthDate,active:true},data.value.deathDate?new Date(`${data.value.deathDate}T12:00:00Z`):new Date()):null)
const date=(value:string)=>new Intl.DateTimeFormat('ru-RU',{timeZone:'UTC',dateStyle:'long'}).format(new Date(`${value.slice(0,10)}T12:00:00Z`))
usePageTitle(()=>data.value?`${data.value.name} — ${role.value==='coach'?'Тренер':'Руководитель'} НБА`:'Профиль тренера или руководителя')
</script>
